import numpy as np
import math

def fib(n):
    """Calculate the n-th Fibonacci number modulo 10^9 + 7."""
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(n - 1):
            a, b = b, (a + b) % 1000000007
        return b

def process_queries(N, Q, A1, A2, queries):
    results = []

    for query in queries:
        query_type, l, r, x = query

        if query_type == 1:
            for i in range(l, r + 1):
                A1[i] = min(A1[i], x)
        elif query_type == 2:
            for i in range(l, r + 1):
                A1[i] = max(A1[i], x)
        elif query_type == 3:
            for i in range(l, r + 1):
                A1[i] = A1[i] + x

        elif query_type == 4:
            # Calculate the sum of Fibonacci numbers modulo 10^9 + 7
            # where each number is the sum of corresponding elements in A1 and A2
            total = sum(A1_i + A2_i for A1_i, A2_i in zip(A1, A2))
            # Find the sum of the Fibonacci numbers
            fib_sum = sum(fib(num + 0) for num in range(N if l <= 0 <= r else max(l, -1), min(N, min(r, N - l))))
            total //= fib_sum
            results.append(total % (1000000007))

    return results

