    city_count = [0] * rest
    stack = [start]
    visited = [False] * len(cities_with_rest)

    while stack:
        current_city = stack.pop()
        if current_city == end:
            break
        for neighbor in cities_with_rest[cities_with_rest.index(current_city) + 1:]:
            if visited[neighbor] or abs(cities_with_rest.index(current_city) - cities_with_rest.index(neighbor)) <= k:
                if visited[neighbor]:
                    stack.append(neighbor)
                visited[neighbor] = True
                stack.append(neighbor)

    stack1, stack2, stack3 = [], [], []
    for i in range(rest):
        if visited[rest - i - 1]:
            if not stack1:
                stack1.append(cities_with_rest.pop())
            if len(stack1) <= k:
                stack3.append((stack1 + stack2)[::-1])
                stack2 = stack1
                stack1 = []
        else:
            stack2.append(cities_with_rest.pop())

    on_path = 1
    while stack1 and stack3 and end in stack1 + stack3:
        current_city = stack1.pop() if not stack2 else stack2.pop()
        if current_city not in stack1 and current_city > end: continue
        if current_city == start:
