from fractions import Fraction


def expected_length():
    MOD = 10**9 + 7

    def dp(n, m, pos):
        if n == m:
            return Fraction(1, 1)

        if pos:
            return Fraction(1, n + 1) * dp(n, m, 0)

        prob = Fraction(1, n - 1)
        cover_uniform = Fraction(1, n - 1) * dp(n - 1, m, 0)
        stay_uniform = Fraction(n - 1, n + 1) * dp(n - 1, m, 1)

