            if len(deque) == 1:
                break
            elif deque[0] < deque[1]:
                start = deque.popleft()
            elif deque[-1] < deque[0]:
                end = deque.pop()
            else:
                break
        else:
            if deque[i] < deque[i-1] and deque[i] < deque[i+1]:
                start = deque.popleft()
            elif deque[i] > deque[i-1] and deque[i] > deque[i+1]:
                end = deque.pop()
            if start and end and start < end:
                return i
    return -1

def preprocess_input(input_str):
