from bisect import bisect_left, bisect_right
from typing import List
from functools import reduce

def find_largest_interesting_number(s: str, t: str, k: int, x: int, y: int) -> int:
    for i in range(k - y, k + x):
        if t <= s[i:]:
            return i + 1
    return -1

class DNA_Editor:
    def __init__(self, s: str, t: str) -> None:
        self.s = s
        self.t = t
        self.length = len(s)
        self.changes = 0
        self.build_changes()

    def build_changes(self) -> None:
        for i in range(self.length):
            if self.s[i] > self.t[i]:
                break
            elif self.s[i] < self.t[i]:
                self.changes += 1
            elif self.s == self.t and i < self.length - 1 and self.s[i] < self.s[i + 1]:
                self.changes += 1
        self.updates = [self.changes]

    def process_updates(self, updates: List[int]) -> None:
        for i, end in enumerate(updates):
            self.updates += [self.changes + (end - 1) if self.changes < end - 1 else self.changes]

    def get_interesting_number(self, l: int, r: int, k: int) -> int:
        if l > r:
            raise ValueError("Invalid range")
        if l == r:
            return reduce(find_largest_interesting_number, (self.s[i:] for i in range(k - l, k + l + 1)), None)
        if l == 0 or r == k:
            return reduce(find_largest_interesting_number, (self.s[i:] for i in range(k - l, k + l + 1)), None)
        lower = bisect_left(self.updates, (r - l + 1) * (k - l) - l)
        if lower < len(self.updates) and (self.updates[lower] < (r - l + 1) * (k - l) - l or (self.updates[lower] == (r - l + 1) * (k - l) - l and l <= self.updates[0])):
            return self.s.index(self.updates[lower], k - l) + lower + 1 - r
        lower = bisect_left(self.updates, (r - l + 1) * (k - l) - (l - 1))
        if lower < len(self.updates) and (self.updates[lower] <= (r - l + 1) * (k - l) - (l - 1) or lower == 0 or self.updates[lower] > (r - l + 1) * (k - l) - (l)): 
            return self.s.index(self.updates[lower], k - l) + lower + 1 - r
        if r < self.length and k <= self.length - (self.length - r - 1):
            return find_largest_interesting_number(self.s, self.t, k, r - min(k, self.length - r - 1), 10)
        raise ValueError("Invalid range")

