def find_divide_point(n, permutation):
    # Calculate the divide point using Floyd's Tortoise and Hare (Cycle Detection)
    slow, fast = 0, 0
    while permutation[slow] % 2 == 0:
        slow += 1
    while permutation[slow] != permutation[fast] and permutation[slow] % 2 == 0:
        slow += 1
        fast = per(n, permutation[slow])
    if permutation[slow] != 1:
        return "NO"
    for i in range(per(n, permutation[slow])):
        if permutation[slow] % 2 or permutation[slow + i] % 2:
            return "NO"
    return "YES"

def per(n, y):
    i = 0
    while y <= n + 1:
        y = (2 * i - 1) * y
        i += 1
    return y

