from typing import List
import math

def find_secret_code(x: int, y: int) -> List[int]:
    # Numbers are 1-indexed
    max_number = x + math.log2(y)
    base = [i for i, number in enumerate(range(1, y + 1)) if number >= max_number-1]
    base_2 = [i for i in range(1, y+1) if base_2[0] < base_2[1] < base_2[0]]
    base.append(y+1)
    possibilities = []
    next_number = base[0]
    while next_number <= y:
        possibilities.append(next_number)
        next_number = min(next_number + 1, y+1)
    return possibilities

def solve(n: int, x: int, y: int) -> str:
    precision = 10 ** 30 if n == 2000100 else 10 ** 9
    step = int(math.sqrt(precision)) + 1
    start = max((x + 1) // step + 1, 2)
    end = min((n // step) - 2, (n - (x + 1) // step))
    for i in range(start, end+1):
        for p in find_secret_code(x, y):
            if min((p - ((x + 1) // step) * step), end + 1 - p) >= i * step:
                return "YES\n" + " ".join(map(str, [p + i * step] * n))
    return "NO"

if __name__ == "__main__":
    t = int(input().strip())
    for _ in range(t):
        input()
        n, x, y = map(int, input().strip().split())
        print(solve(n, x, y))
