from collections import deque
from operator import itemgetter

def process_queries(n, q, queries):
    dp = [0] * n**2
    sum_dp = deque([0])
    fibs = [0, 1]

    for _ in range(n):
        fibs.append(fibs[-1] + fibs[-2])

    for query in queries.values():
        op, l, r, x = query
        if op == 1:
            for i in range(l - 1, r):
                dp[i] = min(dp[i], x)
        elif op == 2:
            for i in range(l - 1, r):
                dp[i] = max(dp[i], x)
        elif op == 3:
            for i in range(l - 1, r):
                dp[i] += x

        nxt = [0]*n**2
        for i in range(n-1):
            for j in range(n-1):
                tmp = dp[i*n**2 + j]
                if i < l-1: tmp = dp[i*n**2 + j] + dp[i*(n-1)**2 + j]
                if j < l-1: tmp = dp[i*n**2 + j] + dp[(i-1)*(n-1)**2 + j]
                if l < i < r: tmp = dp[(i-1)*n**2 + j] + dp[(i)*(n-1)**2 + j]
                if r < j < r: tmp = dp[i*n**2 + (j-1)] + dp[(i+1)*(n-1)**2 + j]
                if l <= i <= r and l <= j <= r: tmp = dp[(i-1)*(n-1)**2 + (j-1)] + dp[(i)*(n-1)**2 + (j)]
                if r < i and r > j: tmp = dp[(i)*(n-1)**2 + (j-1)] + dp[(i-1)*(n-1)**2 + (j-1)]
                if i < l-1 and r < j: tmp = dp[i*(n-1)**2+ (j-1)] + dp[i*(n-1)**2 + (j+1)]
                if j <= r and r < i: tmp = dp[i*n**2 + (j)*(n-1) + 1] + dp[(i+1)*(n-1)**2 + (j-1)]

                nxt[i*n**2 + j] = tmp % (10**9 + 7)
            dp = nxt

        sum_dp.append(dp[-1])
        if len(sum_dp) > 5000000: sum_dp.popleft()

    return [sum(sum_dp[5000000:]) % (10**9 + 7) for _ in range(n)]

