def generate_codes(prefix, codes, total_colors, remaining_indices):
    if not remaining_indices:
        codes.append(prefix)
        return

    for i in range(1, total_colors + 1):
        if i <= remaining_indices[0]:
            codes.append(prefix + str(i))
            generate_codes(prefix + str(i), codes, total_colors, remaining_indices[:1])
            codes.pop()
        remaining_indices[0] -= 1

def find_secret_code(guess, total_colors, n, x, y):
    possible_codes = []
    if n == 1:
        if x == 0:
            return ["1"]
        else:
            return []

    guess.sort()
    remaining_indices = list(range(1, total_colors + 1))

    if x == 0:
        if guess[0] == total_colors + 1:
            if n - y == 1:
                if guess[1] != total_colors + 2:
                    return ["1", "2"]
            else:
                if guess[1] != total_colors + 1:
                    return ["1", "2"]
        else:
            possible_codes.append(["1"])

    elif x == n - 1:
        if guess[-1] == total_colors + 1:
            if n - y == 1:
                if guess[-2] != total_colors + 2:
                    return ["n"]
            else:
                if guess[-2] != total_colors + 1:
                    return ["n"]
        else:
            possible_codes.append(["n"])

    else:
        generate_codes([], possible_codes, total_colors, remaining_indices)
        if x - y > 1:
            possible_codes = [code for code in possible_codes if code.count(guess[0]) >= x - y]

    return possible_codes

